import json
R,C=17,29
G=[[1]*C for _ in range(R)]
# lattice separators
for c in (9,19):
    for r in range(R): G[r][c]=3
for c in range(C): G[8][c]=3
# copy the motif in the upper-left 8x9 panel to every panel (2x3)
motif={(0,0):7,(0,1):9,(2,2):7,(3,5):0}
for r0 in (0,9):
    for c0 in (0,10,20):
        for (dr,dc),v in motif.items(): G[r0+dr][c0+dc]=v
