import json
R,C=17,29
g=[[1]*C for _ in range(R)]
for r in range(R):
    for c in (9,19): g[r][c]=3
for c in range(C): g[8][c]=3
motif={(0,0):7,(0,1):9,(2,2):7,(3,5):0}
for r0 in (0,9):
    for c0 in (0,10,20):
        for (dr,dc),v in motif.items(): g[r0+dr][c0+dc]=v
assert len(g)==17 and all(len(row)==29 for row in g)
assert all(isinstance(x,int) and 0<=x<=9 for row in g for x in row)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
